function makeCounter() {
  let count = 0;

  return function increment() {
    count += 1;
    return count;
  };
}

const counterA = makeCounter();
const counterB = makeCounter();

console.log(counterA()); // 1
console.log(counterA()); // 2
console.log(counterB()); // 1  (separate closure, separate count)

promises.code:
function wait(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function fetchScore(name) {
  return new Promise((resolve, reject) => {
    if (!name) {
      reject(new Error('A name is required'));
      return;
    }
    wait(100).then(() => resolve({ name, score: 42 }));
  });
}

fetchScore('Ada')
  .then((result) => console.log(result.score)) // 42
  .catch((error) => console.error(error.message))
  .finally(() => console.log('done'));

array methods.code:
const orders = [
  { item: 'book', price: 12, shipped: true },
  { item: 'pen', price: 2, shipped: false },
  { item: 'lamp', price: 30, shipped: true },
];

const shippedNames = orders
  .filter((order) => order.shipped)
  .map((order) => order.item);

const total = orders.reduce((sum, order) => sum + order.price, 0);

const hasExpensive = orders.some((order) => order.price > 25);

console.log(shippedNames); // ['book', 'lamp']
console.log(total);        // 44
console.log(hasExpensive); // true

recursion.code:
function sumNested(values) {
  let total = 0;

  for (const value of values) {
    if (Array.isArray(value)) {
      total += sumNested(value); // recursive case
    } else {
      total += value;
    }
  }

  return total; // an empty array returns 0 (base case)
}

console.log(sumNested([1, [2, 3], [4, [5]]])); // 15
console.log(sumNested([]));                    // 0

async/await.code:
function getUser(id) {
  return new Promise((resolve) =>
    setTimeout(() => resolve({ id, name: 'Grace' }), 100)
  );
}

async function greetUser(id) {
  try {
    const user = await getUser(id);
    return `Hello, ${user.name}!`;
  } catch (error) {
    return `Could not load user: ${error.message}`;
  }
}

greetUser(1).then(console.log); // Hello, Grace!

objects.code:
const book = {
  title: 'Eloquent Code',
  author: { name: 'Sam' },
  describe() {
    return `${this.title} by ${this.author.name}`;
  },
};

console.log(book.describe());   // Eloquent Code by Sam
console.log(Object.keys(book)); // ['title', 'author', 'describe']

const shallowCopy = { ...book };
shallowCopy.title = 'Copy';
shallowCopy.author.name = 'Alex'; // shared nested object!

console.log(book.title);       // Eloquent Code
console.log(book.author.name); // Alex
